{"command":"python3 << 'PY'
import workcell
tools = ["station","robot","safety","workcell","cell","admin","operator"]
cmds = ["unsubmit","reopen","reset","unlock","cancel","abort","restart","resume","undo","retract","open","start","continue","clear","status","help"]
for tool in tools:
    for c in cmds:
        r = workcell.call(tool, c)
        t = (r.text or "").strip().replace("\n"," | ")
        interesting = not any(x in t for x in ["unknown command", "usage:", "see ~", "not reachable"])
        if interesting or r.ok:
            print(f"{tool} {c}: ok={r.ok} {t[:300]}")
